'use client';
import { useEffect } from 'react';

// Registers the offline service worker (public/sw.js, generated by next-pwa in production).
// Replaces the plugin's automatic registration, which threw "Cannot read properties of
// undefined (reading 'waiting')" wherever registration is blocked or unsupported.
export default function ServiceWorkerRegistration() {
  useEffect(() => {
    if (process.env.NODE_ENV !== 'production') return;
    if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;

    const register = () => {
      navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(() => {
        // Blocked (private mode, some in-app browsers) — the app still works online.
      });
    };

    if (document.readyState === 'complete') register();
    else {
      window.addEventListener('load', register, { once: true });
      return () => window.removeEventListener('load', register);
    }
  }, []);

  return null;
}
